import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineVAT, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';

test('createInvoice creates a draft invoice with enriched lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  assert.equal(invoice.customerId, 'C-001');
  assert.equal(invoice.issueDate, '2026-10-07');
  assert.equal(invoice.status, 'draft');
  assert.equal(invoice.lines.length, 2);
  assert.deepEqual(invoice.lines[0], {
    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 5,
    unitPrice: 8500,
    vatRate: 21,
    discountPercent: 5,
  });
  assert.deepEqual(invoice.lines[1], {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 3,
    unitPrice: 9500,
    vatRate: 21,
    discountPercent: 5,
  });
});

test('createInvoice normalizes customer ID', () => {
  const r = createInvoice({
    customerId: 'c-001 ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
});

test('createInvoice accepts lowercase and spaced customer IDs', () => {
  const r1 = createInvoice({
    customerId: 'c-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r1.ok, true);
  assert.equal(r1.value.customerId, 'C-002');

  const r2 = createInvoice({
    customerId: ' C-003 ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.customerId, 'C-003');
});

test('createInvoice defaults to NET30 terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET30');
  assert.equal(r.value.dueDate, '2026-11-06');
});

test('createInvoice supports NET14 terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET14');
  assert.equal(r.value.dueDate, '2026-10-21');
});

test('createInvoice supports NET30 terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET30');
  assert.equal(r.value.dueDate, '2026-11-06');
});

test('createInvoice supports EOM terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'EOM');
  assert.equal(r.value.dueDate, '2026-10-31');
});

test('createInvoice reports TERMS_INVALID for unknown terms', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET60',
  }), { ok: false, error: 'TERMS_INVALID' });

  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'INVALID',
  }), { ok: false, error: 'TERMS_INVALID' });
});

test('createInvoice EOM handles different months correctly', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(r1.ok, true);
  assert.equal(r1.value.dueDate, '2026-01-31');

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-02-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.dueDate, '2026-02-28');

  const r3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(r3.ok, true);
  assert.equal(r3.value.dueDate, '2024-02-29');
});

test('createInvoice reports unknown customer', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }), { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports invalid date format', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '10-07-2026',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }), { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports invalid date value', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-02-30',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }), { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports empty lines array', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  }), { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports missing lines', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: null,
  }), { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports non-integer quantity', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1.5 }],
  }), { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports zero quantity', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 0 }],
  }), { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports negative quantity', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: -5 }],
  }), { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports unknown SKU', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'UNKNOWN', qty: 1 }],
  }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice works with products that have different VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  assert.equal(invoice.lines[0].vatRate, 9);
  assert.equal(invoice.lines[1].vatRate, 0);
});

test('createInvoice does not mutate input lines', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 5 }];
  const linesCopy = JSON.stringify(lines);
  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines,
  });
  assert.equal(JSON.stringify(lines), linesCopy);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 8500 }), 42500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 37 }), 3700);
});

test('lineTotal works with large quantities', () => {
  assert.equal(lineTotal({ qty: 1000, unitPrice: 100000 }), 100000000);
});

test('invoiceTotals calculates subtotal and total for single line', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 42500, discount: 0, vat: 0, voucher: 0, total: 42500 });
});

test('invoiceTotals calculates subtotal and total for multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 },
      { qty: 3, unitPrice: 9500 },
      { qty: 100, unitPrice: 37 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 74700, discount: 0, vat: 0, voucher: 0, total: 74700 });
});

test('invoiceTotals works with a real invoice from createInvoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 8 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  const subtotal = 8 * 8500 + 5 * 9500;
  const discount = Math.round(subtotal * 5 / 100);
  const amountAfterDiscount = subtotal - discount;
  const vat = Math.round(amountAfterDiscount * 21 / 100);
  assert.deepEqual(totals, { subtotal, discount, vat, total: subtotal - discount + vat });
});

test('invoiceTotals does not mutate the invoice', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 },
      { qty: 3, unitPrice: 9500 },
    ],
  };
  const invoiceCopy = JSON.stringify(invoice);
  invoiceTotals(invoice);
  assert.equal(JSON.stringify(invoice), invoiceCopy);
});

test('addLine adds a new line to a draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  const r2 = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.deepEqual(r2.value.lines[0].sku, 'DES-HOUR');
  assert.deepEqual(r2.value.lines[1], {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 3,
    unitPrice: 9500,
    vatRate: 21,
    discountPercent: 5,
  });
});

test('addLine increases qty if SKU already exists', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  const r2 = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].qty, 8);
