test('invoiceTotals VAT calculation example', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 2000, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const lineTotal = 100 * 2000;
