import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineVAT, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';

test('createInvoice creates a draft invoice with enriched lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  assert.equal(invoice.customerId, 'C-001');
  assert.equal(invoice.issueDate, '2026-10-07');
  assert.equal(invoice.status, 'draft');
  assert.equal(invoice.lines.length, 2);
  assert.deepEqual(invoice.lines[0], {
    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 5,
    unitPrice: 8500,
    vatRate: 21,
    discountPercent: 5,
  });
  assert.deepEqual(invoice.lines[1], {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 3,
    unitPrice: 9500,
    vatRate: 21,
    discountPercent: 5,
  });
});

test('createInvoice normalizes customer ID', () => {
  const r = createInvoice({
    customerId: 'c-001 ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
});

test('createInvoice accepts lowercase and spaced customer IDs', () => {
  const r1 = createInvoice({
    customerId: 'c-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r1.ok, true);
  assert.equal(r1.value.customerId, 'C-002');

  const r2 = createInvoice({
    customerId: ' C-003 ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.customerId, 'C-003');
});

test('createInvoice defaults to NET30 terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET30');
  assert.equal(r.value.dueDate, '2026-11-06');
});

test('createInvoice supports NET14 terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET14');
  assert.equal(r.value.dueDate, '2026-10-21');
});

test('createInvoice supports NET30 terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET30');
  assert.equal(r.value.dueDate, '2026-11-06');
});

test('createInvoice supports EOM terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'EOM');
  assert.equal(r.value.dueDate, '2026-10-31');
});

test('createInvoice reports TERMS_INVALID for unknown terms', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET60',
  }), { ok: false, error: 'TERMS_INVALID' });

  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'INVALID',
  }), { ok: false, error: 'TERMS_INVALID' });
});

test('createInvoice EOM handles different months correctly', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(r1.ok, true);
  assert.equal(r1.value.dueDate, '2026-01-31');

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-02-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
