});

test('invoiceTotals calculates subtotal and total for single line', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 42500, discount: 0, vat: 0, voucher: 0, total: 42500 });
});

test('invoiceTotals calculates subtotal and total for multiple lines', () => {
  const invoice = {
