  const r3 = addLine(r2.value, { sku: 'COPY-HOUR', qty: 2 });
  assert.equal(r3.ok, true);
  assert.equal(r3.value.lines.length, 3);
  const r4 = removeLine(r3.value, 'DEV-HOUR');
  assert.equal(r4.ok, true);
  assert.equal(r4.value.lines.length, 2);
  assert.deepEqual(r4.value.lines.map(l => l.sku), ['DES-HOUR', 'COPY-HOUR']);
