test('invoiceTotals VAT calculation example', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 2000, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const lineTotal = 100 * 2000;
  const discount = Math.round(lineTotal * 10 / 100);
  const amountAfterDiscount = lineTotal - discount;
  const vat = Math.round(amountAfterDiscount * 21 / 100);
  assert.deepEqual(totals, { subtotal: lineTotal, discount, vat, total: lineTotal - discount + vat });
});

