test('applyVoucher reduces invoice total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  const invoiceWithoutVoucher = r.value;
  const totalsWithout = invoiceTotals(invoiceWithoutVoucher);

  const r2 = applyVoucher(invoiceWithoutVoucher, { code: 'SAVE10', amount: 10000 });
  assert.equal(r2.ok, true);
  const totalsWithVoucher = invoiceTotals(r2.value);
  assert.equal(totalsWithVoucher.voucher, 10000);
