test('invoiceTotals works with voucher', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(r.ok, true);
  const r2 = applyVoucher(r.value, { code: 'SAVE10', amount: 10000 });
  assert.equal(r2.ok, true);
  const totals = invoiceTotals(r2.value);
  const lineTotal = 10 * 8500;
  const discount = Math.round(lineTotal * 5 / 100);
  const amountAfterDiscount = lineTotal - discount;
  const vat = Math.round(amountAfterDiscount * 21 / 100);
  const expectedTotal = lineTotal - discount + vat - 10000;
  assert.deepEqual(totals, { subtotal: lineTotal, discount, vat, voucher: 10000, total: expectedTotal });
});

