test('invoiceTotals includes VAT in result', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21 },
      { qty: 5, unitPrice: 1000, discountPercent: 10, vatRate: 9 },
