  };
  const totals = invoiceTotals(invoice);
  const subtotal = 10000 + 5000;
  const discount = 500;
  const vat = 2100 + 405;
  assert.deepEqual(totals, { subtotal, discount, vat, voucher: 0, total: subtotal - discount + vat });
});

test('invoiceTotals VAT calculation example', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 2000, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const lineTotal = 100 * 2000;
  const discount = Math.round(lineTotal * 10 / 100);
  const amountAfterDiscount = lineTotal - discount;
  const vat = Math.round(amountAfterDiscount * 21 / 100);
  assert.deepEqual(totals, { subtotal: lineTotal, discount, vat, voucher: 0, total: lineTotal - discount + vat });
});

